  LinearLayout root,inputs; RigView rig; TextView status,result,levelText,inspector; Spinner loadCase,viewMode,qProfile; EditText L,D,F,M,stations,layers,actCount,actCapacity,pressure,sf,padW,padL,deflection,linkLength,beamSpan,beamH,beamB,pinAllow,bearingAllow; SeekBar level;
  String[] CASES={"+Z Bending","-Z Bending","+Y Bending","-Y Bending","Pitch +My","Pitch -My","Roll +Mx","Roll -Mx","Yaw +Mz","Yaw -Mz","Combined Z+Pitch"};
  String[] VIEWS={"Interactive Side","Interactive Tree","Mechanical Rig","Beam Detail","Pin/Clevis Detail","Hydraulic","BOM","Validation","Risk Heatmap","Topology Compare","Design Review"};
  String[] Q={"Elliptic","Uniform","Triangular root-high","Triangular tip-high","Parabolic"};

  @Override public void onCreate(Bundle b){super.onCreate(b);
    ScrollView sv=new ScrollView(this); root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(dp(10),dp(10),dp(10),dp(30)); root.setBackgroundColor(NAVY); sv.addView(root);
    root.addView(tx("EFT WHIFFLETREE DIGITAL ENGINEER",25,true,Color.WHITE)); root.addView(tx("v2.1 • explicit 2D layer/actuator visualization • interactive engineering",12,false,Color.rgb(180,205,225)));
    LinearLayout sel=new LinearLayout(this); sel.setOrientation(LinearLayout.HORIZONTAL); loadCase=spin(CASES); viewMode=spin(VIEWS); sel.addView(loadCase,new LinearLayout.LayoutParams(0,dp(50),1)); sel.addView(viewMode,new LinearLayout.LayoutParams(0,dp(50),1)); root.addView(sel,lp());
    status=card("Hazır",Color.rgb(13,47,70)); root.addView(status,lp()); rig=new RigView(); root.addView(rig,new LinearLayout.LayoutParams(-1,dp(720)));
    inspector=card("Çizimde bir station, beam, load-cell veya actuator'a dokun.",Color.rgb(22,45,68)); root.addView(inspector,lp());
    LinearLayout lb=new LinearLayout(this); lb.setOrientation(LinearLayout.VERTICAL); lb.setPadding(dp(8),dp(4),dp(8),dp(4)); lb.setBackground(bg(PANEL,10)); levelText=tx("Load level: 100%",13,true,Color.WHITE); level=new SeekBar(this); level.setMax(100); level.setProgress(100); lb.addView(levelText); lb.addView(level); root.addView(lb,lp());
    inputs=new LinearLayout(this); inputs.setOrientation(LinearLayout.VERTICAL); inputs.setPadding(dp(10),dp(10),dp(10),dp(10)); inputs.setBackground(bg(PANEL,12)); root.addView(inputs,lp()); inputs.addView(tx("DESIGN INPUTS — defaults are editable",17,true,Color.WHITE));
    F=field("Target total load [kN]","305.7"); M=field("Target moment [kN·m]","1280"); L=field("Tank length [m]","7.6"); D=field("Tank diameter [m]","0.64"); stations=field("Station count (4-16)","12"); inputs.addView(tx("q(x) profile",12,true,Color.rgb(185,210,230))); qProfile=spin(Q); inputs.addView(qProfile,lp()); layers=field("Whiffletree layers (1-3)","3"); actCount=field("Actuator count (1-8)","4"); actCapacity=field("Actuator nominal capacity [kN]","120"); pressure=field("Hydraulic pressure [bar]","210"); sf=field("Sizing factor","1.50"); padW=field("Load pad width [mm]","150"); padL=field("Load pad length [mm]","250"); deflection=field("Expected max EFT deflection [mm]","60"); linkLength=field("Nominal link length [mm]","600"); beamSpan=field("Typical beam span [mm]","600"); beamH=field("Beam section height [mm]","80"); beamB=field("Beam section width [mm]","40"); pinAllow=field("Pin allowable shear [MPa]","180"); bearingAllow=field("Lug allowable bearing [MPa]","250");
    Button auto=new Button(this); auto.setText("AUTO OPTIMIZE ACTUATOR COUNT"); auto.setOnClickListener(v->{try{Calc c=compute(true);actCount.setText(""+c.nAct);preview(c);}catch(Exception e){}}); inputs.addView(auto,lp());
    Button best=new Button(this); best.setText("APPLY RECOMMENDED TOPOLOGY"); best.setOnClickListener(v->{try{int[]q=bestTopology();layers.setText(""+q[0]);actCount.setText(""+q[1]);preview(compute(false));}catch(Exception e){}}); inputs.addView(best,lp());
    Button calc=new Button(this); calc.setText("HESAPLA + TÜM 2D GÖRÜNÜMLERİ GÜNCELLE"); calc.setOnClickListener(v->calculate()); inputs.addView(calc,lp());
    result=card("2D çizimde layer sayısı, her layer etiketi ve actuator sayısı doğrudan görünür. Layer/actuator girişini değiştirdiğinde geometri ve sayaçlar anında güncellenir.",Color.rgb(12,34,52)); root.addView(result,lp());
    root.addView(card("Ön tasarım/eğitim aracıdır. Nihai rig release için onaylı loads report, FEM, gerçek katalog ratingleri, allowables ve kurum prosedürleri gerekir.",Color.rgb(66,46,12)),lp());
    TextWatcher tw=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){} public void onTextChanged(CharSequence s,int a,int b,int c){safe();} public void afterTextChanged(Editable e){}}; for(EditText e:new EditText[]{F,M,L,D,stations,layers,actCount,actCapacity,pressure,sf,padW,padL,deflection,linkLength,beamSpan,beamH,beamB,pinAllow,bearingAllow})e.addTextChangedListener(tw);
    android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){rig.clearSelection();safe();}public void onNothingSelected(android.widget.AdapterView<?>p){}}; loadCase.setOnItemSelectedListener(lis); viewMode.setOnItemSelectedListener(lis); qProfile.setOnItemSelectedListener(lis);
    level.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){levelText.setText("Load level: "+p+"%");safe();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}}); setContentView(sv); safe();
  }

  Spinner spin(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
  EditText field(String label,String def){inputs.addView(tx(label,12,true,Color.rgb(185,210,230)));EditText e=new EditText(this);e.setText(def);e.setTextColor(Color.WHITE);e.setTextSize(16);e.setSingleLine(true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);e.setBackground(bg(Color.rgb(25,52,75),8));e.setPadding(dp(10),0,dp(10),0);inputs.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
  void safe(){try{preview(compute(false));}catch(Exception ignored){}}
  void preview(Calc c){rig.set(c,viewMode.getSelectedItemPosition(),level.getProgress()/100.0);status.setText(String.format(Locale.US,"%s • %s • STATIONS %d • LAYERS %d • ACTUATORS %d • %.0f%% load",CASES[loadCase.getSelectedItemPosition()],VIEWS[viewMode.getSelectedItemPosition()],c.n,c.layers,c.nAct,level.getProgress()*1.0));}
  void calculate(){try{Calc c=compute(false);preview(c);int[]bt=bestTopology();result.setText(String.format(Locale.US,"WHIFFLETREE CONFIG: %d LAYERS / %d ACTUATORS\nΣF %.1f kN | M %.1f kN·m | M error %.2f%%\nActuator %.1f kN ea | bore %.1f mm | LC ≥ %.0f kN\nBeam %.1f MPa | Pin Ø%.0f mm | Pad %.2f MPa\nRecommended: %d layers / %d actuators\n\n%s",c.layers,c.nAct,c.sumF,c.calcM,c.mErr,c.actLoad,c.bore,c.lc,c.beamStress,c.pinSel,c.padPressure,bt[0],bt[1],c.gates));}catch(Exception e){result.setText("Girişleri kontrol et.");}}

  Calc compute(boolean opt){Calc c=new Calc();c.L=Math.max(.5,d(L));c.D=Math.max(.1,d(D));c.targetF=Math.abs(d(F));c.targetM=d(M);c.n=clamp((int)Math.round(d(stations)),4,16);c.layers=clamp((int)Math.round(d(layers)),1,3);double cap=Math.max(1,d(actCapacity));c.pbar=Math.max(1,d(pressure));c.sf=Math.max(1,d(sf));c.designF=c.targetF*c.sf;int manual=clamp((int)Math.round(d(actCount)),1,8);int minCap=(int)Math.ceil(c.designF/cap);int minTopo=Math.max(1,(int)Math.ceil(c.n/Math.pow(2,c.layers)));c.nAct=opt?clamp(Math.max(minCap,minTopo),1,8):manual;c.actLoad=c.designF/c.nAct;c.bore=Math.sqrt(4*(c.actLoad*1000)/(c.pbar*100000)/Math.PI)*1000;c.lc=std(c.actLoad*1.2);
    c.x=new double[c.n];c.fi=new double[c.n];double[] w=new double[c.n];double sw=0;int q=qProfile.getSelectedItemPosition();for(int i=0;i<c.n;i++){double u=(i+.5)/c.n;c.x[i]=u*c.L;if(q==0)w[i]=Math.sqrt(Math.max(0,1-Math.pow(2*u-1,2)))+.05;else if(q==1)w[i]=1;else if(q==2)w[i]=1.15-u;else if(q==3)w[i]=.15+u;else w[i]=.25+4*u*(1-u);sw+=w[i];}for(int i=0;i<c.n;i++)c.fi[i]=c.targetF*w[i]/sw;
    double desired=Math.abs(c.targetM),base=0;for(int i=0;i<c.n;i++)base+=c.fi[i]*c.x[i];double mean=0;for(double xx:c.x)mean+=xx;mean/=c.n;double den=0;for(double xx:c.x)den+=(xx-mean)*(xx-mean);double delta=desired-base;if(Math.abs(delta)>1e-9&&den>1e-9)for(int i=0;i<c.n;i++)c.fi[i]+=delta*(c.x[i]-mean)/den;for(int i=0;i<c.n;i++)c.fi[i]=Math.max(.001,c.fi[i]);double ss=0;for(double v:c.fi)ss+=v;for(int i=0;i<c.n;i++)c.fi[i]*=c.targetF/ss;c.sumF=0;c.calcM=0;for(int i=0;i<c.n;i++){c.sumF+=c.fi[i];c.calcM+=c.fi[i]*c.x[i];}if(c.targetM<0)c.calcM=-c.calcM;c.mErr=Math.abs(c.targetM)>1e-6?100*(c.calcM-c.targetM)/Math.abs(c.targetM):0;
    int branch=c.n,beams=0;for(int l=0;l<c.layers&&branch>1;l++){beams+=branch/2;branch=(branch+1)/2;}c.beams=beams;c.topBranches=branch;double def=Math.max(0,d(deflection)),link=Math.max(50,d(linkLength));c.strokeReq=def*1.25+20;c.linkAngle=Math.toDegrees(Math.atan2(def,link));double maxFi=0;for(double f:c.fi)maxFi=Math.max(maxFi,f);c.padArea=Math.max(1,d(padW)*d(padL));c.padPressure=maxFi*1000/(c.padArea/1e6)/1e6;
    double span=Math.max(100,d(beamSpan))/1000.0,bh=Math.max(10,d(beamH))/1000.0,bb=Math.max(10,d(beamB))/1000.0;double Fbeam=Math.max(maxFi*c.sf,c.actLoad)*1000;c.beamM=Fbeam*span/4/1000.0;double I=bb*Math.pow(bh,3)/12;c.beamStress=(c.beamM*1000*(bh/2)/I)/1e6;c.beamDefl=(Fbeam*Math.pow(span,3)/(48*70e9*I))*1000;double tau=Math.max(20,d(pinAllow))*1e6;c.pinReq=Math.sqrt(2*Fbeam/(Math.PI*tau))*1000;c.pinSel=Math.ceil(c.pinReq/2)*2;double bear=Math.max(20,d(bearingAllow))*1e6;c.lugT=(Fbeam/(bear*(c.pinSel/1000)))*1000;c.gates=gates(c,cap);c.bom=bom(c);return c;}
  double topologyScore(int lay,int acts,Calc c){double cap=Math.max(1,d(actCapacity)),dem=c.designF/acts,util=dem/cap;int br=(int)Math.ceil(c.n/Math.pow(2,lay));double s=100-Math.abs(.72-util)*42-acts*2.5-lay*4;if(dem>cap)s-=45;if(br>acts)s-=18*(br-acts);return Math.max(0,Math.min(100,s));}
  int[] bestTopology(){Calc c=compute(false);double best=-1;int bl=c.layers,ba=c.nAct;for(int l=1;l<=3;l++)for(int a=1;a<=8;a++){double s=topologyScore(l,a,c);if(s>best){best=s;bl=l;ba=a;}}return new int[]{bl,ba};}
  String gates(Calc c,double cap){return (Math.abs(c.mErr)<=1?"PASS":"WARN")+" force/moment equivalence\n"+(c.actLoad<=cap?"PASS":"FAIL")+" actuator capacity\n"+(c.linkAngle<=6?"PASS":"WARN")+" link angle\n"+(c.beamStress<180?"PASS":"REVIEW")+" beam training stress\n"+(c.padPressure<8?"PASS":"REVIEW")+" pad mean pressure\n"+(c.strokeReq<=120?"PASS":"WARN")+" stroke envelope";}
  String bom(Calc c){int piv=c.beams*3,links=c.n+Math.max(0,c.beams-c.topBranches),anchors=Math.max(4,c.nAct*2);return "Actuator "+c.nAct+" | Load cell "+c.nAct+" | Servo valve "+c.nAct+" | Beam "+c.beams+" | Pivot/pin "+piv+" | Tie rod "+links+" | Pad "+c.n+" | Floor anchor "+anchors;}
  void showInspector(String s){inspector.setText(s);}

  class Hit{RectF r;String type;int idx;double load;Hit(RectF r,String t,int i,double l){this.r=r;type=t;idx=i;load=l;}}
  class RigView extends View{
    Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG);Calc c;int mode;double lf;ArrayList<Hit> hits=new ArrayList<>();String selType="";int selIdx=-1;
    RigView(){super(MainActivity.this);setBackgroundColor(Color.rgb(4,15,27));t.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));setClickable(true);}
    void set(Calc x,int m,double l){c=x;mode=m;lf=l;invalidate();} void clearSelection(){selType="";selIdx=-1;showInspector("Çizimde bir station, beam, load-cell veya actuator'a dokun.");invalidate();}
    public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;for(Hit h:hits)if(h.r.contains(e.getX(),e.getY())){selType=h.type;selIdx=h.idx;describe(h);invalidate();break;}return true;}
    void describe(Hit h){if(h.type.equals("ST")){int i=Math.min(h.idx,c.n-1);showInspector(String.format(Locale.US,"S%d | %.1f kN | x %.2f m | moment %.1f kN·m",i+1,c.fi[i]*lf,c.x[i],c.fi[i]*c.x[i]*lf));}else if(h.type.equals("ACT"))showInspector(String.format(Locale.US,"ACTUATOR %d/%d | design %.1f kN | current %.1f kN | bore %.1f mm",h.idx+1,c.nAct,c.actLoad,c.actLoad*lf,c.bore));else if(h.type.equals("LC"))showInspector(String.format(Locale.US,"LOAD CELL %d/%d | ≥ %.0f kN | current %.1f kN",h.idx+1,c.nAct,c.lc,c.actLoad*lf));else showInspector(String.format(Locale.US,"BEAM %d | layer tree load %.1f kN | stress %.1f MPa",h.idx+1,h.load*lf,c.beamStress*lf));}
    protected void onDraw(Canvas cn){super.onDraw(cn);hits.clear();if(c==null)return;if(mode==0)drawArticle(cn);else if(mode==1)drawTree(cn,false);else if(mode==2)drawTree(cn,true);else if(mode==3)drawBeam(cn);else if(mode==4)drawPin(cn);else if(mode==5)drawHyd(cn);else if(mode==6)drawBom(cn);else if(mode==7)drawValidation(cn);else if(mode==8)drawHeatmap(cn);else if(mode==9)drawCompare(cn);else drawReview(cn);}
    void title(Canvas cn,String s){t.setColor(Color.WHITE);t.setTextSize(dp(14));cn.drawText(s,dp(12),dp(24),t);configBadge(cn);}
    void configBadge(Canvas cn){float w=getWidth();p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(12,54,78));RectF r=new RectF(w-dp(178),dp(8),w-dp(8),dp(78));cn.drawRoundRect(r,dp(8),dp(8),p);p.setStyle(Paint.Style.STROKE);p.setColor(CYAN);p.setStrokeWidth(2);cn.drawRoundRect(r,dp(8),dp(8),p);t.setColor(CYAN);t.setTextSize(dp(9));cn.drawText("WHIFFLETREE CONFIG",w-dp(168),dp(27),t);t.setColor(Color.WHITE);t.setTextSize(dp(13));cn.drawText(c.layers+" LAYERS",w-dp(168),dp(48),t);cn.drawText(c.nAct+" ACTUATORS",w-dp(168),dp(68),t);}
    void drawTank(Canvas cn,float l,float r,float y){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(48,60,73));cn.drawRoundRect(new RectF(l,y-dp(24),r,y+dp(24)),dp(24),dp(24),p);p.setStyle(Paint.Style.STROKE);p.setColor(STEEL);p.setStrokeWidth(2);cn.drawRoundRect(new RectF(l,y-dp(24),r,y+dp(24)),dp(24),dp(24),p);}
    void drawArticle(Canvas cn){title(cn,"Interactive EFT side view");int w=getWidth(),h=getHeight();float left=w*.07f,right=w*.95f,y=h*.38f;drawTank(cn,left,right,y);for(int i=0;i<c.n;i++){float x=left+(float)(c.x[i]/c.L)*(right-left);p.setColor(CYAN);p.setStrokeWidth(2);cn.drawLine(x,y-dp(28),x,y+dp(28),p);float mag=dp(18)+(float)Math.min(dp(68),c.fi[i]*lf*.8);arrow(cn,x,y-dp(30),0,-mag,BLUE);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("S"+(i+1),x-dp(7),y+dp(43),t);hits.add(new Hit(new RectF(x-dp(18),y-dp(100),x+dp(18),y+dp(50)),"ST",i,c.fi[i]));}dimension(cn,left,right,y+dp(95),String.format(Locale.US,"L = %.2f m",c.L));drawMiniTopology(cn,h*.68f);}
    ArrayList<float[]> baseNodes(float left,float right,float y){ArrayList<float[]>n=new ArrayList<>();for(int i=0;i<c.n;i++){float x=left+(float)(c.x[i]/c.L)*(right-left);n.add(new float[]{x,y,(float)(c.fi[i]*c.sf)});}return n;}
    void drawTree(Canvas cn,boolean mech){title(cn,mech?"Mechanical Rig — Layer/Actuator Map":"Whiffletree 2D — Layer/Actuator Map");int w=getWidth(),h=getHeight();float left=w*.05f,right=w*.95f,tankY=dp(105);drawTank(cn,left,right,tankY);ArrayList<float[]>nodes=baseNodes(left,right,tankY+dp(30));int beamId=0;float base=tankY+dp(82);for(int lev=1;lev<=c.layers&&nodes.size()>1;lev++){ArrayList<float[]>nx=new ArrayList<>();float yy=base+dp(72)*(lev-1);p.setStyle(Paint.Style.FILL);p.setColor(lev==1?ORANGE:(lev==2?YELLOW:CYAN));cn.drawRoundRect(new RectF(dp(5),yy-dp(15),dp(78),yy+dp(15)),dp(5),dp(5),p);t.setColor(NAVY);t.setTextSize(dp(9));cn.drawText("LAYER "+lev,dp(12),yy+dp(4),t);for(int i=0;i<nodes.size();i+=2){if(i+1<nodes.size()){float[]a=nodes.get(i),b=nodes.get(i+1);float sum=a[2]+b[2],px=(a[0]*b[2]+b[0]*a[2])/sum;p.setColor(lev==1?ORANGE:(lev==2?YELLOW:CYAN));p.setStrokeWidth(mech?7:5);cn.drawLine(a[0],yy,b[0],yy,p);p.setStrokeWidth(2);cn.drawLine(a[0],a[1],a[0],yy,p);cn.drawLine(b[0],b[1],b[0],yy,p);p.setStyle(Paint.Style.FILL);cn.drawCircle(px,yy,dp(5),p);p.setStyle(Paint.Style.STROKE);hits.add(new Hit(new RectF(Math.min(a[0],b[0])-dp(8),yy-dp(18),Math.max(a[0],b[0])+dp(8),yy+dp(18)),"BEAM",beamId++,sum));nx.add(new float[]{px,yy,sum});}else nx.add(nodes.get(i));}nodes=nx;}
      float ay=Math.min(h-dp(100),base+dp(72)*c.layers+dp(42));t.setTextSize(dp(10));t.setColor(GREEN);cn.drawText("ACTUATOR COUNT = "+c.nAct,dp(12),ay-dp(70),t);for(int a=0;a<c.nAct;a++){float x=w*(a+1f)/(c.nAct+1f);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(80,95,110));RectF ar=new RectF(x-dp(20),ay-dp(48),x+dp(20),ay);cn.drawRoundRect(ar,dp(5),dp(5),p);hits.add(new Hit(ar,"ACT",a,c.actLoad));if(mech){p.setColor(RED);RectF lr=new RectF(x-dp(15),ay-dp(68),x+dp(15),ay-dp(51));cn.drawRect(lr,p);hits.add(new Hit(lr,"LC",a,c.lc));p.setColor(YELLOW);cn.drawCircle(x,ay-dp(78),dp(7),p);}p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);float tx=nodes.get(Math.min(a,nodes.size()-1))[0],ty=nodes.get(Math.min(a,nodes.size()-1))[1];cn.drawLine(x,ay-dp(48),tx,ty,p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("ACTUATOR "+(a+1),x-dp(28),ay+dp(18),t);}}
    void drawMiniTopology(Canvas cn,float y){int w=getWidth();t.setColor(Color.WHITE);t.setTextSize(dp(10));cn.drawText("2D TOPOLOGY: "+c.layers+" layers / "+c.nAct+" actuators",dp(15),y,t);float yy=y+dp(28);for(int l=1;l<=c.layers;l++){p.setColor(l==1?ORANGE:(l==2?YELLOW:CYAN));p.setStrokeWidth(5);cn.drawLine(dp(90),yy,w-dp(22),yy,p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("L"+l,dp(18),yy+dp(4),t);yy+=dp(28);}for(int a=0;a<c.nAct;a++){float x=w*(a+1f)/(c.nAct+1f);p.setStyle(Paint.Style.FILL);p.setColor(GREEN);cn.drawRect(x-dp(8),yy,x+dp(8),yy+dp(32),p);t.setColor(Color.WHITE);t.setTextSize(dp(7));cn.drawText("A"+(a+1),x-dp(7),yy+dp(45),t);}}
    void drawBeam(Canvas cn){title(cn,"Beam Detail");textBlock(cn,new String[]{String.format(Locale.US,"Mmax %.2f kN·m",c.beamM),String.format(Locale.US,"Stress %.1f MPa",c.beamStress),String.format(Locale.US,"Deflection %.2f mm",c.beamDefl)},dp(20),dp(150));}
    void drawPin(Canvas cn){title(cn,"Pin / Clevis Detail");textBlock(cn,new String[]{String.format(Locale.US,"Required pin %.1f mm",c.pinReq),String.format(Locale.US,"Selected Ø%.0f mm",c.pinSel),String.format(Locale.US,"Lug t min %.1f mm",c.lugT)},dp(20),dp(150));}
    void drawHyd(Canvas cn){title(cn,"Hydraulic Architecture — "+c.nAct+" actuator channels");float y=dp(120);box(cn,dp(20),y,dp(90),dp(55),"HPU");box(cn,dp(135),y,dp(100),dp(55),"Manifold");for(int a=0;a<c.nAct;a++){float yy=y+dp(100)+a*dp(48);box(cn,dp(55),yy,dp(100),dp(34),"SV"+(a+1));box(cn,dp(200),yy,dp(120),dp(34),"ACT"+(a+1));}}
    void drawBom(Canvas cn){title(cn,"Dynamic BOM");textBlock(cn,c.bom.split(" \\| "),dp(18),dp(110));}
    void drawValidation(Canvas cn){title(cn,"Validation Matrix");textBlock(cn,c.gates.split("\\n"),dp(18),dp(110));}
    void drawHeatmap(Canvas cn){title(cn,"EFT Load / Risk Heatmap");int w=getWidth(),h=getHeight();float l=w*.07f,r=w*.95f,y=h*.35f;drawTank(cn,l,r,y);double mx=0;for(double f:c.fi)mx=Math.max(mx,f);for(int i=0;i<c.n;i++){float x=l+(float)(c.x[i]/c.L)*(r-l);double u=c.fi[i]/mx;p.setStyle(Paint.Style.FILL);p.setColor(u<.55?GREEN:(u<.8?YELLOW:RED));cn.drawCircle(x,y,dp(10)+(float)dp(15)*(float)u,p);}drawMiniTopology(cn,h*.65f);}
    void drawCompare(Canvas cn){title(cn,"Topology Compare");int[]bt=bestTopology();float y=dp(105);for(int l=1;l<=3;l++)for(int a=2;a<=6;a++){double s=topologyScore(l,a,c);float x=dp(18)+(a-2)*dp(66),yy=y+(l-1)*dp(110);p.setStyle(Paint.Style.FILL);p.setColor(l==bt[0]&&a==bt[1]?GREEN:(s>60?Color.rgb(40,75,92):YELLOW));cn.drawRoundRect(new RectF(x,yy,x+dp(56),yy+dp(78)),dp(6),dp(6),p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("L"+l+" A"+a,x+dp(6),yy+dp(20),t);cn.drawText(String.format(Locale.US,"%.0f",s),x+dp(15),yy+dp(48),t);}}
    void drawReview(Canvas cn){title(cn,"Design Review");int[]bt=bestTopology();textBlock(cn,new String[]{"CURRENT: "+c.layers+" LAYERS / "+c.nAct+" ACTUATORS","RECOMMENDED: "+bt[0]+" LAYERS / "+bt[1]+" ACTUATORS",String.format(Locale.US,"Moment error %.2f%%",c.mErr),String.format(Locale.US,"Actuator demand %.1f kN",c.actLoad),String.format(Locale.US,"Beam stress %.1f MPa",c.beamStress),String.format(Locale.US,"Pad pressure %.2f MPa",c.padPressure)},dp(18),dp(115));}
    void arrow(Canvas cn,float x,float y,float dx,float dy,int col){p.setColor(col);p.setStrokeWidth(4);cn.drawLine(x,y,x+dx,y+dy,p);}
    void dimension(Canvas cn,float a,float b,float y,String s){p.setColor(STEEL);p.setStrokeWidth(1);cn.drawLine(a,y,b,y,p);t.setColor(Color.WHITE);t.setTextSize(dp(9));cn.drawText(s,(a+b)/2-dp(28),y-dp(6),t);}
    void box(Canvas cn,float x,float y,float w,float h,String s){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(40,63,82));cn.drawRoundRect(new RectF(x,y,x+w,y+h),dp(6),dp(6),p);t.setColor(Color.WHITE);t.setTextSize(dp(9));cn.drawText(s,x+dp(8),y+h/2+dp(4),t);}
    void textBlock(Canvas cn,String[]lines,float x,float y){t.setColor(Color.WHITE);t.setTextSize(dp(10));for(String s:lines){cn.drawText(s,x,y,t);y+=dp(30);}}
  }

  static class Calc{double L,D,targetF,targetM,pbar,sf,designF,actLoad,bore,lc,sumF,calcM,mErr,strokeReq,linkAngle,padArea,padPressure,beamM,beamStress,beamDefl,pinReq,pinSel,lugT;int n,layers,nAct,beams,topBranches;double[]x,fi;String bom,gates;}
  double std(double v){double[]a={10,20,25,50,75,100,150,200,250,300,500,750,1000};for(double x:a)if(x>=v)return x;return Math.ceil(v/100)*100;} double d(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));} int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));} int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;} TextView tx(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;} TextView card(String s,int c){TextView v=tx(s,13,false,Color.WHITE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(bg(c,10));return v;} GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
